bject": "EJA - Geografia", "axis": "2º SEGMENTO"}, {"code": "EJA-CL08-GEO10", "name": "Investigar as desigualdades sociais e territoriais no Brasil, com foco em moradia,…", "description": "Investigar as desigualdades sociais e territoriais no Brasil, com foco em moradia, saneamento e acesso a serviços básicos.", "grade_level": "8ª Etapa", "competency": "Geografia", "subject": "EJA - Geografia", "axis": "2º SEGMENTO"}, {"code": "EJA-CL08-GEO11", "name": "Produzir e analisar mapas temáticos com base em dados oficiais (IBGE, INPE, SEMARH) sobre…", "description": "Produzir e analisar mapas temáticos com base em dados oficiais (IBGE, INPE, SEMARH) sobre o município e o estado.", "grade_level": "8ª Etapa", "competency": "Geografia", "subject": "EJA - Geografia", "axis": "2º SEGMENTO"}, {"code": "EJA-CL08-GEO12", "name": "Compreender os conceitos de trabalho informal e do subemprego e identificar o fator…", "description": "Compreender os conceitos de trabalho informal e do subemprego e identificar o fator positivo para mudar a realidade do desemprego estrutural.", "grade_level": "8ª Etapa", "competency": "Geografia", "subject": "EJA - Geografia", "axis": "2º SEGMENTO"}, {"code": "EJA-CL08-GEO13", "name": "Elaborar propostas de intervenção no espaço vivido a partir da leitura crítica do…", "description": "Elaborar propostas de intervenção no espaço vivido a partir da leitura crítica do território e do diálogo com a comunidade local.", "grade_level": "8ª Etapa", "competency": "Geografia", "subject": "EJA - Geografia", "axis": "2º SEGMENTO"}, {"code": "EJA-CL08-HIS01", "name": "Compreender os principais acontecimentos da História Contemporânea e sua influência no…", "description": "Compreender os principais acontecimentos da História Contemporânea e sua influência no Brasil.", "grade_level": "8ª Etapa", "competency": "História", "subject": "EJA - História", "axis": "2º SEGMENTO"}, {"code": "EJA-CL08-HIS02", "name": "Analisar, criticamente os principais acontecimentos da histó